package io.github.byshadow64.tgproxy.core

import org.junit.Assert.*
import org.junit.Test
import java.security.MessageDigest

class ProtocolVectorsTest {
    private val secret = hex("000102030405060708090a0b0c0d0e0f")
    private val init = hex("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f30313233343536377fb7a7ad45f7ade4")

    /** Generated by the unchanged desktop _try_handshake/_generate_relay_init/_build_crypto_ctx on 2026-10-27. */
    @Test fun matchesExistingPythonImplementationExactly() {
        val handshake = Obfuscated2.parse(init, secret)!!
        assertEquals(4, handshake.dc); assertTrue(handshake.media)
        assertEquals(TransportProtocol.PADDED_INTERMEDIATE, handshake.protocol)
        val relay = Obfuscated2.relayInit(handshake) { size -> if (size == 64) ByteArray(64) { (it + 64).toByte() } else hex("9192") }
        assertArrayEquals(hex("404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f606162636465666768696a6b6c6d6e6f70717273747576778cc1af92ada5e61b"), relay)
        val crypto = Obfuscated2.context(handshake, secret, relay)
        val plain = ByteArray(64) { (it + 1).toByte() }
        assertArrayEquals(hex("57dccf6e1f776b45d5492a055d3f324c1c6e2044d976f9864bf4da418b03ab6d81e5488dc20db60fd03ee05d33e62c144700808be12d7df8ae2cc3639d6d6bff"), crypto.clientDecrypt.update(plain))
        assertArrayEquals(hex("a10bd48c814152e93089f47c6f44362b6b129d790e08cd2de13968c2b71c3cdde94ebcbfe7d8dfa389525da5c90de4fc1c3d23953347c8dbced6bd1d2962893d"), crypto.clientEncrypt.update(plain))
        assertArrayEquals(hex("530b6e2f932c99e913d8cc7dcc20928b87c5d3e7a4ece877db93ad186e3936d1640d77319f2faca2be68a83662a97c2eee7477730ad7d6871ebeb87362e31010"), crypto.telegramEncrypt.update(plain))
        assertArrayEquals(hex("7e74cdbca8cb9a50debcee634753d38b4e99e0cbb0be9b9b33cdd62e4c35d51fe6007123dddbaa5957600997d52ef6fe5f3506177a62bf7898ade266b85c3547"), crypto.telegramDecrypt.update(plain))
    }

    @Test fun supportsAllThreeProtocolsAndRejectsWrongSecret() {
        for (protocol in TransportProtocol.entries) {
            val bytes = clientInit(secret, protocol, 2)
            assertEquals(protocol, Obfuscated2.parse(bytes, secret)!!.protocol)
            assertNull(Obfuscated2.parse(bytes, ByteArray(16) { 99 }))
        }
        assertNull(Obfuscated2.parse(ByteArray(63), secret))
        assertNull(Obfuscated2.parse(clientInit(secret, TransportProtocol.INTERMEDIATE, 0), secret))
    }

    @Test fun ctrStreamDoesNotDependOnChunkBoundaries() {
        val key = ByteArray(32) { it.toByte() }; val iv = ByteArray(16) { (it + 44).toByte() }
        val data = ByteArray(1024 * 1024 + 19) { (it * 31).toByte() }
        val expected = StreamCipher(key, iv).update(data)
        val cipher = StreamCipher(key, iv)
        val output = java.io.ByteArrayOutputStream()
        var offset = 0
        while (offset < data.size) { val count = minOf(7919, data.size - offset); output.write(cipher.update(data.copyOfRange(offset, offset + count))); offset += count }
        assertArrayEquals(expected, output.toByteArray())
    }
}

internal fun hex(value: String) = ByteArray(value.length / 2) { value.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

internal fun clientInit(secret: ByteArray, protocol: TransportProtocol, dc: Int): ByteArray {
    val raw = ByteArray(64) { it.toByte() }
    for (i in 56..59) raw[i] = protocol.tag.toByte()
    raw[60] = dc.toByte(); raw[61] = (dc shr 8).toByte()
    val key = MessageDigest.getInstance("SHA-256").digest(raw.copyOfRange(8, 40) + secret)
    val encrypted = StreamCipher(key, raw.copyOfRange(40, 56)).update(raw)
    return raw.copyOf().also { encrypted.copyInto(it, 56, 56, 64) }
}
